const lockProjectUpdateRecipients = `-- name: LockProjectUpdateRecipients :many
SELECT user_id FROM member WHERE workspace_id=$1 AND user_id=ANY($2::uuid[]) ORDER BY user_id FOR SHARE NOWAIT
`

type LockProjectUpdateRecipientsParams struct {
	WorkspaceID pgtype.UUID   `json:"workspace_id"`
	UserIds     []pgtype.UUID `json:"user_ids"`
}

func (q *Queries) LockProjectUpdateRecipients(ctx context.Context, arg LockProjectUpdateRecipientsParams) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, lockProjectUpdateRecipients, arg.WorkspaceID, arg.UserIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []pgtype.UUID{}
	for rows.Next() {
		var user_id pgtype.UUID
		if err := rows.Scan(&user_id); err != nil {
			return nil, err
		}
		items = append(items, user_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const retryProjectUpdateNotification = `-- name: RetryProjectUpdateNotification :exec
UPDATE project_update_notification SET attempts=attempts+1,status=CASE WHEN attempts+1>=12 THEN 'dead_letter' ELSE 'pending' END,
next_attempt_at=$1,last_error_code=$2 WHERE id=$3 AND workspace_id=$4 AND status='pending'
`

type RetryProjectUpdateNotificationParams struct {
	NextAttemptAt pgtype.Timestamptz `json:"next_attempt_at"`
	LastErrorCode pgtype.Text        `json:"last_error_code"`
	ID            pgtype.UUID        `json:"id"`
	WorkspaceID   pgtype.UUID        `json:"workspace_id"`
}

func (q *Queries) RetryProjectUpdateNotification(ctx context.Context, arg RetryProjectUpdateNotificationParams) error {
	_, err := q.db.Exec(ctx, retryProjectUpdateNotification,
		arg.NextAttemptAt,
		arg.LastErrorCode,
		arg.ID,
		arg.WorkspaceID,
	)
	return err
}
